fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Assumes start + sub.len() <= main.len()
    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // If sub is empty, it is always a subarray
    if sub.is_empty() {
        return true;
    }
    // If sub is longer than main, can't be a subarray
    if sub.len() > main.len() {
        return false;
    }

    // Iterate over all possible start indices where sub could fit
    let max_start = main.len() - sub.len();
    for start in 0..=max_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }

    false
}